method(as_json, list(ProviderOpenAI, ContentToolRequestSearch)) <- function(
  provider,
  x,
  ...
) {
  openai_replay_annotation(x)
}

method(as_json, list(ProviderOpenAI, ContentToolRequestFetch)) <- function(
  provider,
  x,
  ...
) {
  openai_replay_annotation(x)
}

openai_replay_annotation <- function(content) {
  if (
    !is.null(content@extra) &&
      identical(content@extra$type, "web_search_call")
  ) {
    content@extra
  }
}
